import argparse
import json
import os
from pathlib import Path

from datasets import Dataset, concatenate_datasets
from PIL import Image


# <LAO-X>/third_party/CutLER/export_hf_det_compass_to_coco_agnostic.py
LAOX_ROOT = Path(__file__).resolve().parents[2]
DEFAULT_DATA_ROOT = Path(os.environ.get("LAOX_DATA_ROOT", LAOX_ROOT / "datasets")) / "det_compass_xp"
# PAGF/DET-COMPASS as cached by `datasets.load_dataset("PAGF/det-compass")`.
HF_DATASET_SUBDIR = Path("PAGF___det-compass") / "default" / "0.0.0"
HF_DATASET_REVISION = "8b53b83d0a698a87a9a96e7d9f91895408f33b40"


def default_hf_datasets_cache():
    """Resolve the HuggingFace datasets cache like `datasets` does (HF_DATASETS_CACHE,
    then HF_HOME/datasets, then XDG_CACHE_HOME/huggingface/datasets)."""
    if os.environ.get("HF_DATASETS_CACHE"):
        return Path(os.environ["HF_DATASETS_CACHE"]).expanduser()
    if os.environ.get("HF_HOME"):
        return Path(os.environ["HF_HOME"]).expanduser() / "datasets"
    xdg = os.environ.get("XDG_CACHE_HOME") or os.path.join("~", ".cache")
    return Path(xdg).expanduser() / "huggingface" / "datasets"


def default_cache_dir():
    """Arrow-shard dir of DET-COMPASS: the LAO-X revision if cached, else the only cached one."""
    base = default_hf_datasets_cache() / HF_DATASET_SUBDIR
    preferred = base / HF_DATASET_REVISION
    if preferred.is_dir():
        return preferred
    revisions = sorted(p for p in base.glob("*") if p.is_dir()) if base.is_dir() else []
    return revisions[0] if len(revisions) == 1 else preferred


def parse_args():
    parser = argparse.ArgumentParser(
        description=(
            "Export PAGF/DET-COMPASS annotations matched to local xray images "
            "into a category-agnostic COCO json."
        )
    )
    parser.add_argument(
        "--xray-dir",
        type=Path,
        default=DEFAULT_DATA_ROOT / "xray",
        help="Directory containing local xray images.",
    )
    parser.add_argument(
        "--matches-path",
        type=Path,
        default=DEFAULT_DATA_ROOT / "annotations" / "huggingface_matches.json",
        help="Path to huggingface_matches.json generated by the matching step.",
    )
    parser.add_argument(
        "--cache-dir",
        type=Path,
        default=None,
        help=(
            "Directory containing cached DET-COMPASS arrow shards (det-compass-<split>-*.arrow). "
            "Default: <HF datasets cache>/" + HF_DATASET_SUBDIR.as_posix() + "/<revision>."
        ),
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=DEFAULT_DATA_ROOT / "annotations" / "coco_agnostic_1928.json",
        help="Output COCO json path.",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=None,
        help="Only export the first N local images after sorting.",
    )
    parser.add_argument(
        "--annotation-splits",
        nargs="+",
        default=["test", "invisible"],
        help="Only write annotations from these matched HuggingFace splits.",
    )
    return parser.parse_args()


def load_matches(matches_path):
    with matches_path.open("r") as f:
        data = json.load(f)
    return data.get("matches", {})


def load_split_dataset(cache_dir, split):
    shard_paths = sorted(cache_dir.glob(f"det-compass-{split}-*.arrow"))
    if not shard_paths:
        raise FileNotFoundError(f"No arrow shards found for split '{split}' under {cache_dir}")
    datasets = [Dataset.from_file(str(path)) for path in shard_paths]
    dataset = concatenate_datasets(datasets) if len(datasets) > 1 else datasets[0]
    remove_columns = [col for col in ("rgb_image", "xray_images") if col in dataset.column_names]
    if remove_columns:
        dataset = dataset.remove_columns(remove_columns)
    return dataset


def resolve_image_id(image_path, fallback_id):
    try:
        return int(image_path.stem)
    except ValueError:
        return fallback_id


def build_coco(xray_paths, matches, datasets_by_split, annotation_splits):
    images = []
    annotations = []
    ann_id = 0
    annotation_splits = set(annotation_splits)

    for fallback_image_id, image_path in enumerate(xray_paths):
        entries = matches.get(image_path.name, [])
        split = None
        sample_index = None
        for entry in entries:
            split_name = entry.get("split")
            if split_name in datasets_by_split:
                split = split_name
                sample_index = entry.get("index")
                break

        with Image.open(image_path) as img:
            width, height = img.size

        image_id = resolve_image_id(image_path, fallback_image_id)
        images.append(
            {
                "id": image_id,
                "width": width,
                "height": height,
                "file_name": image_path.name,
                "license": 0,
                "flickr_url": "",
                "coco_url": "",
                "date_captured": 0,
            }
        )

        if split is None or sample_index is None:
            continue
        if split not in annotation_splits:
            continue

        sample = datasets_by_split[split][int(sample_index)]
        objects = sample.get("objects") or {}
        bboxes = objects.get("xray_bbox") or []
        visibles = objects.get("xray_visible") or []

        for object_index, bbox in enumerate(bboxes):
            if not bbox or len(bbox) != 4:
                continue
            x, y, w, h = [float(v) for v in bbox]
            visible = True
            if object_index < len(visibles):
                visible = bool(visibles[object_index])
            annotations.append(
                {
                    "id": ann_id,
                    "image_id": image_id,
                    "category_id": 1,
                    "segmentation": [],
                    "area": float(w * h),
                    "bbox": [x, y, w, h],
                    "iscrowd": 0,
                    "visible": visible,
                }
            )
            ann_id += 1

    return {
        "images": images,
        "annotations": annotations,
        "categories": [{"id": 1, "name": "object"}],
    }


def main():
    args = parse_args()
    if args.cache_dir is None:
        args.cache_dir = default_cache_dir()

    if not args.xray_dir.is_dir():
        raise FileNotFoundError(f"Missing xray directory: {args.xray_dir}")
    if not args.matches_path.is_file():
        raise FileNotFoundError(f"Missing matches file: {args.matches_path}")
    if not args.cache_dir.is_dir():
        raise FileNotFoundError(f"Missing cache directory: {args.cache_dir}")

    matches = load_matches(args.matches_path)
    datasets_by_split = {
        "test": load_split_dataset(args.cache_dir, "test"),
        "invisible": load_split_dataset(args.cache_dir, "invisible"),
    }

    xray_paths = sorted(args.xray_dir.glob("*.png"))
    if args.limit is not None:
        xray_paths = xray_paths[: args.limit]
    if not xray_paths:
        raise RuntimeError(f"No xray images found under {args.xray_dir}")

    coco = build_coco(
        xray_paths,
        matches,
        datasets_by_split,
        annotation_splits=args.annotation_splits,
    )
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("w") as f:
        json.dump(coco, f)

    print(
        f"Finished: {len(coco['images'])} images, "
        f"{len(coco['annotations'])} annotations. Output: {args.output}"
    )


if __name__ == "__main__":
    main()
